WITH exploded AS (SELECT id, service, host, log_ts, level, latency_ms, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) e AS key, attr_value) SELECT CASE WHEN latency_ms >= 2304 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, service, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN key = 'trace' THEN 1 END), 0), 2) AS latency_ms_per_trace, MIN(log_ts) AS first_seen, BIT_OR(latency_ms) AS latency_ms_bit_or FROM exploded GROUP BY CASE WHEN latency_ms >= 2304 THEN 'PREMIUM' ELSE 'STANDARD' END, service ORDER BY latency_ms_per_trace;
